import{_ as e,c as t,o as r,ae as l}from"./chunks/framework.DNEoaTf_.js";const q=JSON.parse('{"title":"よくある質問（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/faq.md","filePath":"ja/faq.md"}'),i={name:"ja/faq.md"};function o(h,a,u,s,n,d){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="よくある質問-faq" tabindex="-1">よくある質問（FAQ） <a class="header-anchor" href="#よくある質問-faq" aria-label="Permalink to &quot;よくある質問（FAQ）&quot;">​</a></h1><h2 id="一般的な質問" tabindex="-1">一般的な質問 <a class="header-anchor" href="#一般的な質問" aria-label="Permalink to &quot;一般的な質問&quot;">​</a></h2><h3 id="q-この拡張機能は無料ですか" tabindex="-1">Q: この拡張機能は無料ですか？ <a class="header-anchor" href="#q-この拡張機能は無料ですか" aria-label="Permalink to &quot;Q: この拡張機能は無料ですか？&quot;">​</a></h3><p>はい、完全に無料です。オープンソースプロジェクトとして公開されています。</p><h3 id="q-どのブラウザに対応していますか" tabindex="-1">Q: どのブラウザに対応していますか？ <a class="header-anchor" href="#q-どのブラウザに対応していますか" aria-label="Permalink to &quot;Q: どのブラウザに対応していますか？&quot;">​</a></h3><p>以下のブラウザに対応しています：</p><ul><li>Google Chrome</li><li>Microsoft Edge</li><li>Brave</li><li>Firefox（予定）</li><li>その他 Chromium ベースのブラウザ</li></ul><h3 id="q-データはどこに保存されますか" tabindex="-1">Q: データはどこに保存されますか？ <a class="header-anchor" href="#q-データはどこに保存されますか" aria-label="Permalink to &quot;Q: データはどこに保存されますか？&quot;">​</a></h3><p>動画IDと設定情報は、ブラウザのローカルストレージ（<code>chrome.storage.local</code>）に保存されます。外部サーバーには一切送信されません。</p><h3 id="q-オフラインでも使えますか" tabindex="-1">Q: オフラインでも使えますか？ <a class="header-anchor" href="#q-オフラインでも使えますか" aria-label="Permalink to &quot;Q: オフラインでも使えますか？&quot;">​</a></h3><p>いいえ、サムネイル情報は YouTube の API からリアルタイムで取得するため、インターネット接続が必要です。ただし、設定情報はローカルに保存されるため、オフラインでも設定は保持されます。</p><h2 id="機能について" tabindex="-1">機能について <a class="header-anchor" href="#機能について" aria-label="Permalink to &quot;機能について&quot;">​</a></h2><h3 id="q-どのサイズのサムネイルをダウンロードできますか" tabindex="-1">Q: どのサイズのサムネイルをダウンロードできますか？ <a class="header-anchor" href="#q-どのサイズのサムネイルをダウンロードできますか" aria-label="Permalink to &quot;Q: どのサイズのサムネイルをダウンロードできますか？&quot;">​</a></h3><p>以下の解像度のサムネイルが取得可能です（動画により異なります）：</p><ul><li>maxresdefault (1280x720 または 1920x1080)</li><li>sddefault (640x480)</li><li>hqdefault (480x360)</li><li>mqdefault (320x180)</li><li>default (120x90)</li></ul><h3 id="q-webp-形式のサムネイルは取得できますか" tabindex="-1">Q: WebP 形式のサムネイルは取得できますか？ <a class="header-anchor" href="#q-webp-形式のサムネイルは取得できますか" aria-label="Permalink to &quot;Q: WebP 形式のサムネイルは取得できますか？&quot;">​</a></h3><p>はい、YouTube が提供している場合は、JPG と WebP の両方の形式で取得可能です。</p><h3 id="q-youtube-shorts-にも対応していますか" tabindex="-1">Q: YouTube Shorts にも対応していますか？ <a class="header-anchor" href="#q-youtube-shorts-にも対応していますか" aria-label="Permalink to &quot;Q: YouTube Shorts にも対応していますか？&quot;">​</a></h3><p>はい、対応しています。通常の動画と同じ方法でサムネイルを取得できます。</p><h3 id="q-プレイリストや検索結果ページでも使えますか" tabindex="-1">Q: プレイリストや検索結果ページでも使えますか？ <a class="header-anchor" href="#q-プレイリストや検索結果ページでも使えますか" aria-label="Permalink to &quot;Q: プレイリストや検索結果ページでも使えますか？&quot;">​</a></h3><p>いいえ、この拡張機能は個別の動画再生ページでのみ動作します。</p><h2 id="プライバシーとセキュリティ" tabindex="-1">プライバシーとセキュリティ <a class="header-anchor" href="#プライバシーとセキュリティ" aria-label="Permalink to &quot;プライバシーとセキュリティ&quot;">​</a></h2><h3 id="q-youtube-のログイン情報は保存されますか" tabindex="-1">Q: YouTube のログイン情報は保存されますか？ <a class="header-anchor" href="#q-youtube-のログイン情報は保存されますか" aria-label="Permalink to &quot;Q: YouTube のログイン情報は保存されますか？&quot;">​</a></h3><p>いいえ、ログイン情報は一切保存しません。拡張機能は YouTube の公開 API を利用してサムネイル情報を取得します。</p><h3 id="q-第三者にデータは共有されますか" tabindex="-1">Q: 第三者にデータは共有されますか？ <a class="header-anchor" href="#q-第三者にデータは共有されますか" aria-label="Permalink to &quot;Q: 第三者にデータは共有されますか？&quot;">​</a></h3><p>いいえ、一切共有されません。サムネイルは YouTube から直接取得し、ユーザーのブラウザで表示されます。</p><h3 id="q-使用状況の統計は収集されますか" tabindex="-1">Q: 使用状況の統計は収集されますか？ <a class="header-anchor" href="#q-使用状況の統計は収集されますか" aria-label="Permalink to &quot;Q: 使用状況の統計は収集されますか？&quot;">​</a></h3><p>いいえ、アナリティクスやトラッキングは一切実装していません。</p><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><h3 id="q-一部のサムネイルが表示されないのですが" tabindex="-1">Q: 一部のサムネイルが表示されないのですが？ <a class="header-anchor" href="#q-一部のサムネイルが表示されないのですが" aria-label="Permalink to &quot;Q: 一部のサムネイルが表示されないのですが？&quot;">​</a></h3><p>maxresdefault（最大画質）は、すべての動画で利用可能とは限りません。YouTube が高解像度のサムネイルを生成していない場合、低解像度のサムネイルのみが表示されます。</p><h3 id="q-拡張機能が動作しません" tabindex="-1">Q: 拡張機能が動作しません <a class="header-anchor" href="#q-拡張機能が動作しません" aria-label="Permalink to &quot;Q: 拡張機能が動作しません&quot;">​</a></h3><ol><li>YouTube の動画再生ページにいるか確認してください</li><li>ブラウザを再起動してみてください</li><li>拡張機能を無効化→有効化してみてください</li><li>それでも解決しない場合は、<a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で報告してください</li></ol><h2 id="開発・貢献" tabindex="-1">開発・貢献 <a class="header-anchor" href="#開発・貢献" aria-label="Permalink to &quot;開発・貢献&quot;">​</a></h2><h3 id="q-オープンソースですか" tabindex="-1">Q: オープンソースですか？ <a class="header-anchor" href="#q-オープンソースですか" aria-label="Permalink to &quot;Q: オープンソースですか？&quot;">​</a></h3><p>はい、MIT ライセンスで公開されています。<a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub リポジトリ</a>をご覧ください。</p><h3 id="q-機能のリクエストやバグ報告はどこでできますか" tabindex="-1">Q: 機能のリクエストやバグ報告はどこでできますか？ <a class="header-anchor" href="#q-機能のリクエストやバグ報告はどこでできますか" aria-label="Permalink to &quot;Q: 機能のリクエストやバグ報告はどこでできますか？&quot;">​</a></h3><p><a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で受け付けています。</p><h3 id="q-開発に参加したいのですが" tabindex="-1">Q: 開発に参加したいのですが？ <a class="header-anchor" href="#q-開発に参加したいのですが" aria-label="Permalink to &quot;Q: 開発に参加したいのですが？&quot;">​</a></h3><p>大歓迎です！プルリクエストをお待ちしています。<a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub リポジトリ</a>をご覧ください。</p><h3 id="q-使用している技術スタックは" tabindex="-1">Q: 使用している技術スタックは？ <a class="header-anchor" href="#q-使用している技術スタックは" aria-label="Permalink to &quot;Q: 使用している技術スタックは？&quot;">​</a></h3><ul><li>WXT (Framework)</li><li>React</li><li>TypeScript</li><li>Tailwind CSS</li></ul><div class="tip custom-block"><p class="custom-block-title">さらに質問がありますか？</p><p>このページで解決しない場合は、<a href="https://github.com/mosunset/youtube_watch_thumbnails/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> でお気軽にお聞きください。</p></div>',43)])])}const c=e(i,[["render",o]]);export{q as __pageData,c as default};
